st.markdown('<div class="sec-title">Business Insights</div>', unsafe_allow_html=True)

def insight(tone, ic, title, body):
    st.markdown(
        f'<div class="icard ic-{tone}"><div class="icard-title">{icon(ic,16)} {title}</div>'
        f'<div class="icard-body">{body}</div></div>',
        unsafe_allow_html=True
    )

ins1, ins2 = st.columns(2)

with ins1:
    if clean_pct >= 70:
        tone, ic, title = "success", "check-circle", "Order Quality is Healthy"
        body = f"<strong>{clean_pct}%</strong> of orders are passing validation — a strong baseline. Keep monitoring for city-level spikes on a weekly basis."
    elif clean_pct >= 50:
        tone, ic, title = "warning", "alert-triangle", "Order Quality Needs Attention"
        body = f"Only <strong>{clean_pct}%</strong> are confirmed clean. Review top-risk cities and add address hints at checkout to improve this number."
    else:
        tone, ic, title = "danger", "alert-octagon", "Order Quality is Critical"
        body = f"Only <strong>{clean_pct}%</strong> passing — over half your orders carry risk. Review your checkout flow and address requirements immediately."
    insight(tone, ic, title, body)

    per1k = round(saved * 1000 / max(1, total))
    insight("success", "shield", "AI System Value Generated",
        f"Caught <strong>{rejected} bad orders</strong> before dispatch — protecting <strong>Rs {saved:,}</strong> from RTO losses.<br>"
        f"At current rates: <strong>Rs {per1k:,} saved per 1,000 orders</strong> processed.")

    daily_est = max(1, round(total / 7))
    net       = (saved * 4) - (rto_loss * 4)
    nc        = "#0B7A54" if net >= 0 else "#C23A29"
    insight("neutral", "trending-up", "Monthly Financial Projection",
        f"~{daily_est} orders/day estimate based on current data<br>"
        f"Projected RTO loss: <strong>Rs {rto_loss*4:,}</strong><br>"
        f"Projected AI savings: <strong>Rs {saved*4:,}</strong><br>"
        f"Net position: <strong style='color:{nc};font-size:15px'>Rs {net:,}</strong>")

    if pending > 0:
        insight("warning", "clock", f"{pending} Orders Not Yet Processed",
            "These orders are stuck in <strong>Pending</strong> status — the AI validation hasn't run yet. "
            "Check your n8n workflow. They may be stuck at the Wait node or failed at the Gemini step.")

    if cancelled > 0:
        cancel_pct = round(cancelled / total * 100, 1) if total else 0
        insight("neutral", "ban", f"{cancelled} Orders Cancelled by Customer",
            f"<strong>{cancel_pct}%</strong> of processed orders were cancelled after the customer "
            "was contacted — worth reviewing if this rate climbs, it may signal address-confirmation friction.")

with ins2:
    if "city" in df_proc.columns and total > 0:
        cr = df_proc[df_proc["status"].isin(["Risk Flagged","Rejected"])]["city"].value_counts()
        ct = df_proc["city"].value_counts()
        if not cr.empty:
            tc = cr.index[0]; tn = cr.iloc[0]
            tt = ct.get(tc, 1); tp = round(tn/tt*100,1)
            insight("danger", "map-pin", f"Highest Risk City: {tc}",
                f"<strong>{tn} flagged or rejected</strong> out of {tt} orders from {tc} — that's a <strong>{tp}% risk rate</strong>.<br>"
                f"Consider adding stricter address validation at checkout specifically for {tc} orders.")

        crate = {}
        for city in ct.index:
            cdf = df_proc[df_proc["city"] == city]
            if len(cdf) >= 2:
                crate[city] = len(cdf[cdf["status"].isin(["Risk Flagged","Rejected"])]) / len(cdf)
        if crate:
            sc2 = min(crate, key=crate.get)
            sp  = round(crate[sc2]*100,1)
            insight("success", "check-circle", f"Most Reliable City: {sc2}",
                f"Only <strong>{sp}% risk rate</strong> on orders from {sc2}.<br>"
                "Consider auto-confirming low-value orders from this city to speed up dispatch.")

    insight("warning", "bar-chart", "Risk Score Breakdown",
        f"<strong>{critical_cnt} orders</strong> scored 85+ — high confidence fake or bad address<br>"
        f"<strong>{border_cnt} orders</strong> scored 60–84 — borderline, manual review strongly advised<br>"
        f"Overall average: <strong>{avg_risk}</strong> &nbsp;·&nbsp; Flagged orders average: <strong>{avg_fl_risk}</strong>")

    wce = money_at_risk + rto_loss
    insight("danger", "alert-octagon", "Total Current Exposure",
        f"<strong>Rs {wce:,}</strong> currently exposed to delivery risk<br>"
        f"Rs {money_at_risk:,} — flagged orders not dispatched (still recoverable)<br>"
        f"Rs {rto_loss:,} — already lost to shipping + reverse logistics")

# ════════════════════════════════════════════════════════
# ORDER TABLE
# ════════════════════════════════════════════════════════
col_t1, col_t2 = st.columns([8, 2])
with col_t1:
    st.markdown('<div class="sec-title">Order Details</div>', unsafe_allow_html=True)

show_cols = ["name","phone","address","clean_address","city","status",
             "risk_score","risk_level","risk_reason","map_status","created_at"]
show_cols = [c for c in show_cols if c in df_view.columns]

def style_status(val):
    m = {"Rejected":       "background:#FDF0EE;color:#C23A29;font-weight:700",
         "Risk Flagged":   "background:#FFF7EB;color:#B4650A;font-weight:700",
         "Auto-Confirmed": "background:#EEFBF5;color:#0B7A54;font-weight:700",
         "Confirmed":      "background:#EEFBF5;color:#0B7A54;font-weight:700",
         "Cancelled":      "background:#F5F3EA;color:#6B6449;font-weight:700",
         "Manual Review":  "background:#F5EEDD;color:#8A6D3B;font-weight:700"}
    return m.get(val, "")

def style_risk(val):
    m = {"CRITICAL": "background:#FDF0EE;color:#C23A29;font-weight:700",
         "HIGH":     "background:#FDF0EE;color:#C23A29",
         "MEDIUM":   "background:#FFF7EB;color:#B4650A",
         "LOW":      "background:#EEFBF5;color:#0B7A54"}
    return m.get(val, "")

st.caption(f"Showing **{len(df_view)}** of **{total}** processed orders · **{pending}** pending excluded")

styled = df_view[show_cols].style
if "status"     in show_cols: styled = styled.map(style_status, subset=["status"])
if "risk_level" in show_cols: styled = styled.map(style_risk,   subset=["risk_level"])
if "risk_score" in show_cols:
    styled = styled.background_gradient(subset=["risk_score"], cmap="RdYlGn_r", vmin=0, vmax=100)

table_config = {
    "name":          st.column_config.TextColumn("Customer",      width=120),
    "phone":         st.column_config.TextColumn("Phone",         width=115),
    "address":       st.column_config.TextColumn("Raw Address",   width=230),
    "clean_address": st.column_config.TextColumn("Clean Address", width=230),
    "city":          st.column_config.TextColumn("City",          width=95),
    "status":        st.column_config.TextColumn("Status",        width=135),
    "risk_score":    st.column_config.NumberColumn("Score",       width=72, format="%d"),
    "risk_level":    st.column_config.TextColumn("Level",         width=80),
    "risk_reason":   st.column_config.TextColumn("Reason",        width=290),
    "map_status":    st.column_config.TextColumn("Maps",          width=115),
    "created_at":    st.column_config.TextColumn("Date",          width=88),
}

@st.dialog("Full Screen Order Intelligence Log", width="large")
def fullscreen_table():
    st.dataframe(styled, use_container_width=True, height=700, column_config=table_config, hide_index=True)

with col_t2:
    st.write("")
    if st.button("⛶ Open Full Screen Table", use_container_width=True):
        fullscreen_table()

st.dataframe(
    styled,
    use_container_width=True,
    height=440,
    hide_index=True,
    column_config=table_config
)

